mapper.select:
SELECT wmrs.id, wm.sys_classify AS sysClassify, wm.module_classify AS moduleClassify, db.name AS moduleStatusName, wmrs.module_status, wm.sys_menu_id FROM work_menu wm LEFT JOIN work_menu_ref_status wmrs ON wm.id = wmrs.menu_id LEFT JOIN dict_basic db ON wmrs.module_status = db."value" AND db."type" = 'moduleStatus'
AND wm.sys_classify = #{sysClassify}
ORDER BY wm.sys_classify,wm.id

SELECT max(wmrs.id) id, wm.sys_classify AS sysClassify, wm.module_classify AS moduleClassify, '' AS moduleStatusName FROM work_menu wm LEFT JOIN work_menu_ref_status wmrs ON wm.id = wmrs.menu_id LEFT JOIN dict_basic db ON wmrs.module_status = db."value"
AND wm.sys_classify = #{sysClassify}
GROUP BY wm.sys_classify, wm.module_classify ORDER BY sys_classify,max(wmrs.id)

SELECT wo.id, wmrs.id AS moduleStatusId, wm.id AS menu_id, wm.sys_classify AS sysClassify, wm.module_classify AS moduleClassify, wm.module_code AS moduleCode, db.name AS moduleStatusName, wmrs.module_status_field AS moduleStatusField, wmrs.module_status AS moduleStatus, wmrs.module_url AS moduleUrl, wmrs.module_param AS moduleParam, wmrs.table_field AS tableField, wmrs.menu_code AS menuCode, wmrs.is_approval_workflow AS isApprovalWorkflow FROM work_option wo LEFT JOIN work_menu_ref_status wmrs ON wo.work_menu_id = wmrs.id LEFT JOIN work_menu wm ON wm.id = wmrs.menu_id LEFT JOIN dict_basic db ON wmrs.module_status = db."value" WHERE wo.is_deleted = FALSE AND wo.type = '1' AND wm.module_code NOT IN ('qcInfo')
AND wo.option_user_id = #{optionUserId}
ORDER BY wm.sys_classify,wm.id

SELECT wo.id, wmrs.id AS moduleStatusId, CASE WHEN wm.sys_classify IS NULL THEN SUBSTRING(wo.module_url,2,3) ELSE wm.sys_classify END AS sysClassify, wm.id AS menu_id, CASE WHEN wm.module_classify IS NULL THEN wo.module_name ELSE wm.module_classify END AS name, CASE WHEN wmrs.module_url IS NULL THEN wo.module_url ELSE wmrs.module_url END AS moduleUrl, wmrs.module_param AS moduleParam, wo.module_name AS moduleName FROM work_option wo LEFT JOIN work_menu_ref_status wmrs ON wo.work_menu_id = wmrs.id LEFT JOIN work_menu wm ON wm.id = wmrs.menu_id LEFT JOIN dict_basic db ON wmrs.module_status = db."value" WHERE wo.is_deleted = FALSE AND wo.type = '2'
AND wo.option_user_id = #{optionUserId}
ORDER BY wo.id asc

SELECT max(ptm.id) AS id, wm.module_classify as moduleClassify, pm.business_code as businessCode, pm.business_name as businessName, pm.business_id as businessId, pm.business_key as businessKey, pm.create_user_id as createUserId, COALESCE(EXTRACT(EPOCH FROM (pm.end_time - pm.start_time)),0) AS approveDuration, pm.create_time as createTime, pm.approve_status as approveStatus, case when wm.is_multi_tab = true then replace(concat(wm.detail_url,pm.business_id), '?', concat('/',pm.business_id,'?')) else concat(wm.detail_url,pm.business_id) end as detailUrl, wmrs.cancel_process_url as cancelProcessUrl, wmrs.cancel_process_param as cancelProcessParam FROM process_management pm INNER JOIN process_task_management ptm ON pm.process_instance_id = ptm.process_instance_id AND ptm.is_deleted = FALSE INNER JOIN work_menu wm ON pm.business_key = wm.module_code AND wm.is_deleted = FALSE LEFT JOIN work_menu_ref_status wmrs ON wmrs.menu_id = wm.id LEFT JOIN process_task_cc cc ON cc.task_management_id = ptm.id AND cc.is_deleted = FALSE WHERE pm.is_deleted = FALSE
AND ptm.task_status = 'approveIng' and pm.approve_status = 'approveIng' AND ptm.cur_approve_id = #{params.userId}
AND (ptm.task_status = 'approve' OR ptm.task_status = 'reject') AND ptm.cur_approve_id = #{params.userId}
AND cc.cc_user_id = #{params.userId}
AND pm.create_user_id = #{params.userId}
AND wm.sys_classify IN
#{item}
AND pm.business_code ilike concat('%',#{params.sourceCode}::text,'%')
AND pm.create_user_id IN
#{item}
AND pm.create_time >= #{params.createTimeList[0]} and (#{params.createTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > pm.create_time
GROUP BY moduleClassify, businessCode, businessName, businessId, businessKey, createUserId, approveDuration, createTime, approveStatus, detailUrl, cancelProcessUrl, cancelProcessParam
ORDER BY
${item.field} ${item.sort}

SELECT count(*) AS quantity, t.sys_classify FROM ( SELECT max(ptm.id) AS id, wm.module_classify, pm.business_code, pm.business_name, pm.business_id, pm.business_key, pm.create_user_id, EXTRACT(EPOCH FROM (pm.end_time - pm.start_time)) AS approveDuration, pm.create_time, pm.approve_status, wm.sys_classify, concat(wm.detail_url,pm.business_id) as detail_url FROM process_management pm INNER JOIN process_task_management ptm ON pm.process_instance_id = ptm.process_instance_id AND ptm.is_deleted = FALSE INNER JOIN work_menu wm ON pm.business_key = wm.module_code AND wm.is_deleted = FALSE LEFT JOIN process_task_cc cc ON cc.task_management_id = ptm.id AND cc.is_deleted = FALSE WHERE pm.is_deleted = FALSE
AND ptm.task_status = 'approveIng' AND ptm.cur_approve_id = #{params.userId}
AND (ptm.task_status = 'approve' OR ptm.task_status = 'reject') AND ptm.cur_approve_id = #{params.userId}
AND cc.cc_user_id = #{params.userId}
AND pm.create_user_id = #{params.userId}
AND wm.sys_classify IN
#{item}
AND pm.business_code ilike concat('%',#{params.sourceCode}::text,'%')
GROUP BY wm.module_classify, pm.business_code, pm.business_name, pm.business_id, pm.business_key, pm.create_user_id, wm.sys_classify, EXTRACT(EPOCH FROM (pm.end_time - pm.start_time)), pm.create_time, pm.approve_status, concat(wm.detail_url,pm.business_id) )t GROUP BY t.sys_classify
